type DynError = Box<dyn std::error::Error>;
type Result<T> = std::result::Result<T, DynError>;

fn err(msg: impl Into<String>) -> DynError {
    Box::new(std::io::Error::other(msg.into()))
}

// Extended-frame-bounds and cloaked attribute ids (stable DWM ABI).
const DWMWA_EXTENDED_FRAME_BOUNDS: u32 = 9;
const DWMWA_CLOAKED: u32 = 14;
const MONITORINFOF_PRIMARY: u32 = 1;
// Win32 object id for window-scoped events (filters out menu/scrollbar noise).
const OBJID_WINDOW: i32 = 0;
const TICK_POLL_MS: u32 = 100;
const SLOW_POLL_MS: u64 = 2000;
// Pumped focus-settle bound: re-reads of `GetForegroundWindow` after an
// accepted setter, 50 ms pumped each so the LL-hook message pump stays live.
// No foreign wait: `pump_wait` only services the owner's own queue.
const FOCUS_SETTLE_ROUNDS: u32 = 10;
const FOCUS_SETTLE_POLL_MS: u32 = 50;

/// Shell classes that are never tile targets.
fn is_shell_class(class: &str) -> bool {
    matches!(
        class,
        "Progman" | "WorkerW" | "Shell_TrayWnd" | "Shell_SecondaryTrayWnd" | "DV2ControlHost"
    )
}

/// Border-only shell-popup exclusion: the KDE `isAppletPopup` analogue.
/// Targeted, never blanket: ordinary dialogs (`#32770`), tool windows,
/// owned windows, and `explorer.exe` file browsers stay eligible. Only exact
/// shell classes plus XAML-island shell hosts gated on the shell process
/// suppress the ring. Task View suspension also hides the owned surface.
fn is_border_shell_popup(class: &str, exe_file: &str) -> bool {
    if crate::product_hide::shell_class_excluded(class) {
        return true;
    }
    if matches!(
        class,
        "MultitaskingViewFrame" | "TaskSwitcherWnd" | "NotifyIconOverflowWindow" | "Shell_Flyout"
    ) {
        return true;
    }
    // XAML-island shell surfaces (Start, Search, Widgets): class alone is
    // generic, so require the shell experience process. Never matches
    // explorer.exe file browsers or ApplicationFrameHost store apps.
    if class == "Windows.UI.Core.CoreWindow" || class == "XamlExplorerHostIslandWindow" {
        return matches!(
            exe_file,
            "startmenuexperiencehost.exe"
                | "shellexperiencehost.exe"
                | "searchhost.exe"
                | "searchui.exe"
                | "widgets.exe"
                | "textinputhost.exe"
        );
    }
    false
}

fn exe_file_name(exe_path: &str) -> &str {
    exe_path.rsplit(['/', '\\']).next().unwrap_or(exe_path)
}

/// Generic Win32 dialog class. Unowned top-level dialogs are never tile
/// targets; owned ones are already excluded as owned dialogs. The project's
/// own Settings UI (own executable plus settings class) rides the same gate
/// via [`crate::tiling::is_own_settings_window`].
const DIALOG_CLASS: &str = "#32770";

fn rect_from_win(rect: RECT) -> Option<Rect> {
    let w = (rect.right as i64 - rect.left as i64).try_into().ok()?;
    let h = (rect.bottom as i64 - rect.top as i64).try_into().ok()?;
    if w <= 0 || h <= 0 {
        return None;
    }
    Some(Rect {
        x: rect.left,
        y: rect.top,
        w,
        h,
    })
}

/// Verify Per-Monitor-V2 awareness before any geometry call. Checks the
/// effective context first (a manifest may already set it) and only sets when
/// needed, verifying afterward. Fails closed: a wrong awareness mode
/// silently virtualizes every rectangle.
pub(crate) fn ensure_pm_v2() -> Result<()> {
    let current = unsafe { GetThreadDpiAwarenessContext() };
    if unsafe { AreDpiAwarenessContextsEqual(current, DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2) }
        != 0
    {
        return Ok(());
    }
    if unsafe { SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2) } == 0 {
        return Err(err("refuse: SetProcessDpiAwarenessContext failed"));
    }
    let current = unsafe { GetThreadDpiAwarenessContext() };
    if unsafe { AreDpiAwarenessContextsEqual(current, DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2) }
        == 0
    {
        return Err(err("refuse: PMv2 awareness not active"));
    }
    Ok(())
}

#[derive(Debug, Clone)]
struct MonitorArea {
    /// Stable session key: the device name (`szDevice`, e.g. `\\.\DISPLAY1`).
    /// Rectangles decide placement; this key decides session identity.
    device: String,
    work: Rect,
    full: Rect,
}

unsafe extern "system" fn monitor_enum(
    monitor: HMONITOR,
    _hdc: HDC,
    _rect: *mut RECT,
    state: LPARAM,
) -> i32 {
    let out = unsafe { &mut *(state as *mut Vec<MonitorArea>) };
    let mut info: MONITORINFOEXW = unsafe { std::mem::zeroed() };
    info.monitorInfo.cbSize = std::mem::size_of::<MONITORINFOEXW>() as u32;
    if unsafe { GetMonitorInfoW(monitor, (&mut info as *mut MONITORINFOEXW).cast()) } == 0 {
        return 1;
    }
    let work = RECT {
        left: info.monitorInfo.rcWork.left,
        top: info.monitorInfo.rcWork.top,
        right: info.monitorInfo.rcWork.right,
        bottom: info.monitorInfo.rcWork.bottom,
    };
    let full = RECT {
        left: info.monitorInfo.rcMonitor.left,
        top: info.monitorInfo.rcMonitor.top,
        right: info.monitorInfo.rcMonitor.right,
        bottom: info.monitorInfo.rcMonitor.bottom,
    };
    if let (Some(work), Some(full)) = (rect_from_win(work), rect_from_win(full)) {
        let end = info
            .szDevice
            .iter()
            .position(|c| *c == 0)
            .unwrap_or(info.szDevice.len());
        let device = String::from_utf16_lossy(&info.szDevice[..end]);
        let device = if device.is_empty() {
            "display-?".to_owned()
        } else {
            device
        };
        let area = MonitorArea { device, work, full };
        let primary = info.monitorInfo.dwFlags & MONITORINFOF_PRIMARY != 0;
        if primary {
            out.insert(0, area);
        } else {
            out.push(area);
        }
    }
    1
}

/// All monitor areas in physical pixels, primary first. Fails when no
/// monitor enumerates: the caller retains Engine state and skips the tick.
fn all_monitors() -> Result<Vec<MonitorArea>> {
    let mut areas: Vec<MonitorArea> = Vec::new();
    let ok = unsafe {
        EnumDisplayMonitors(
            std::ptr::null_mut(),
            std::ptr::null(),
            Some(monitor_enum),
            &mut areas as *mut Vec<MonitorArea> as LPARAM,
        )
    };
    if ok == 0 || areas.is_empty() {
        return Err(err("error: monitor enumeration failed"));
    }
    Ok(areas)
}

/// Full `rcMonitor` bounds of every display for the portable fullscreen
/// predicate (whole-monitor coverage, not work area).
fn monitor_fulls(areas: &[MonitorArea]) -> Vec<Rect> {
    areas.iter().map(|a| a.full).collect()
}

// Hook delivery: out-of-context callbacks run on the installing (loop) thread
// while it pumps messages, so the callback and the loop share one queue lock
// with a strict invariant - the loop never holds it across a message pump -
// and the callback takes it blocking (never try_lock-and-drop, lossless).
#[derive(Debug, Clone, Copy)]
enum HookEvent {
    Wake(isize),
    /// Esc sequence captured at WinEvent delivery time in the event
    /// callback, carried to START. The pump only carries it to the START
    /// snapshot and never re-reads it later, so an Esc that arrives
    /// between the real START and the owner drain still latches (mirrors
    /// the KDE Finish pointer on MoveSizeEnd).
    MoveSizeStart(isize, u64),
    /// Release cursor captured at WinEvent delivery time in the event
    /// callback, carried to settle. `None` when the read failed: settle
    /// routes cursor-less moves as no-change. Captured here (the KDE Finish
    /// pointer), never re-read later on the pump. The END-time Esc sequence
    /// rides along so a physical Esc AFTER the END (before the owner drain)
    /// can never cancel the completed drop: settle latches ended gestures
    /// only when the END snapshot differs from START.
    MoveSizeEnd(isize, Option<(i32, i32)>, u64),
}

fn hook_queue() -> &'static Mutex<Vec<HookEvent>> {
    static QUEUE: OnceLock<Mutex<Vec<HookEvent>>> = OnceLock::new();
    QUEUE.get_or_init(|| Mutex::new(Vec::new()))
}

fn push_hook(event: HookEvent) {
    if let Ok(mut queue) = hook_queue().lock() {
        queue.push(event);
    }
}

unsafe extern "system" fn winevent_proc(
    _hook: HWINEVENTHOOK,
    event: u32,
    hwnd: HWND,
    id_object: i32,
    _id_child: i32,
    _thread: u32,
    _time: u32,
) {
    if event == EVENT_SYSTEM_MOVESIZESTART {
        // Event-time Esc sequence sampled directly from the shared atomic
        // clock, so a physical Esc between the real START and the owner
        // drain keeps a newer sequence than the snapshot and still latches.
        // Delayed batch sequences never decide this comparison.
        push_hook(HookEvent::MoveSizeStart(
            hwnd as isize,
            crate::snapkey::sys::shared_esc_seq(),
        ));
    } else if event == EVENT_SYSTEM_MOVESIZEEND {
        // KDE Finish pointer: capture the release cursor now, at event
        // time in the callback. The pump only carries it to settle and
        // never re-reads it later. The END-time Esc sequence is captured
        // alongside so post-END edges order correctly at the drain.
        push_hook(HookEvent::MoveSizeEnd(
            hwnd as isize,
            cursor_pos(),
            crate::snapkey::sys::shared_esc_seq(),
        ));
    } else if id_object == OBJID_WINDOW
        && matches!(
            event,
            EVENT_SYSTEM_FOREGROUND
                | EVENT_OBJECT_CREATE
                | EVENT_OBJECT_DESTROY
                | EVENT_OBJECT_SHOW
                | EVENT_OBJECT_HIDE
                | EVENT_OBJECT_LOCATIONCHANGE
        )
    {
        push_hook(HookEvent::Wake(hwnd as isize));
    }
}

/// Product outer wait: pump loop-thread messages (delivering hook callbacks)
/// then wait for more plus the input-pump intent wake and the renderer ack
/// wake. Returns what woke the wait so the loop can drain an ack-only wake
/// without reposting frames, reconciling, or polling settings: renderer acks
/// wake the owner immediately with no polling latency, but an ack alone
/// never triggers owner work by itself, so the ack wake cannot feed back
/// into a post/ack/post busy loop. A pending wake (offered before this wait)
/// returns immediately; bursts coalesce to one wake; the timeout keeps the
/// periodic follow cadence (timed native reassert included). One thread owns
/// install, pump, and uninstall: no join, no hang.
fn pump_wait_with_intent(
    timeout_ms: u32,
    wake: Option<&OwnedHandle>,
    ack_wake: Option<&OwnedHandle>,
) -> WaitWake {
    let mut msg: MSG = unsafe { std::mem::zeroed() };
    loop {
        let has = unsafe { PeekMessageW(&mut msg, std::ptr::null_mut(), 0, 0, PM_REMOVE) };
        if has == 0 {
            break;
        }
        unsafe {
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }
    }
    let mut woke = WaitWake {
        input: false,
        ack: false,
        message: false,
        timeout: false,
        failed: false,
    };
    unsafe {
        let mut handles = [std::ptr::null_mut(); 2];
        let mut count: u32 = 0;
        if let Some(handle) = wake {
            handles[0] = handle.as_handle().as_raw_handle();
            count = 1;
        }
        if let Some(handle) = ack_wake {
            handles[count as usize] = handle.as_handle().as_raw_handle();
            count += 1;
        }
        let result = if count == 0 {
            MsgWaitForMultipleObjectsEx(0, std::ptr::null(), timeout_ms, QS_ALLINPUT, 0)
        } else {
            MsgWaitForMultipleObjectsEx(count, handles.as_ptr(), timeout_ms, QS_ALLINPUT, 0)
        };
        const WAIT_OBJECT_0: u32 = 0;
        const WAIT_TIMEOUT: u32 = 258;
        if result == WAIT_TIMEOUT {
            woke.timeout = true;
        } else if result < WAIT_OBJECT_0 + count {
            // A satisfied wait object: index 0 is the input wake when
            // present, else the ack wake; index 1 is the ack wake.
            let has_input = wake.is_some();
            if result == WAIT_OBJECT_0 && has_input {
                woke.input = true;
            } else {
                woke.ack = true;
            }
        } else if result == WAIT_OBJECT_0 + count {
            woke.message = true;
        } else {
            // WAIT_FAILED or abandoned: counted separately as `failed`, never
            // merged into `timeout` (genuine 258 only). Control flow keeps the
            // existing fallback: a failed return takes the periodic-work path
            // below like before, with no new recovery and no timing claim (a
            // failed wait returns immediately; not proven delayed).
            woke.failed = true;
        }
    }
    loop {
        let has = unsafe { PeekMessageW(&mut msg, std::ptr::null_mut(), 0, 0, PM_REMOVE) };
        if has == 0 {
            break;
        }
        // Dispatched callbacks below may queue hook events: once any
        // message flows, this turn does full owner work even when the wait
        // itself returned an ack or timeout reason.
        woke.message = true;
        unsafe {
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }
    }
    woke
}

/// What woke the product outer wait: any combination may hold (an ack plus
/// queued messages is common). `timeout` is the genuine deadline expiry
/// (`WAIT_TIMEOUT` 258) only; `failed` is `WAIT_FAILED`/abandoned, counted
/// separately and never merged into timeout. Ack-only turns drain acks and
/// service the pending finish without reposting, reconciling, or
/// settings/input work.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct WaitWake {
    input: bool,
    ack: bool,
    message: bool,
    timeout: bool,
    failed: bool,
}

impl WaitWake {
    /// Full owner turn: fresh input, real messages, the genuine periodic
    /// timeout (which preserves the timed follow/reassert cadence), or the
    /// pre-existing failed-wait fallback path (unchanged control flow; only
    /// the counter differs). Hook-callback events collected after the wait
    /// also force a full turn at the call site, so no input starves behind
    /// ack traffic.
    #[must_use]
    const fn full_turn(self) -> bool {
        self.input || self.message || self.timeout || self.failed
    }
}

/// Trace-only outer-wait return counts (outer product wait only; the
/// focus/proof `pump_wait` path never constructs one of these). Reason hits
/// count set `WaitWake` flags per return, so combinations (ack plus messages
/// is common) can exceed `waits`; `timeout` counts genuine 258 expiries only
/// while `failed` counts `WAIT_FAILED`/abandoned separately; `ack_only`
/// counts the early-return subset.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct OwnerWaitCounts {
    waits: u64,
    ack_only: u64,
    input: u64,
    ack: u64,
    msg: u64,
    timeout: u64,
    failed: u64,
}

impl OwnerWaitCounts {
    /// One outer wait return: one `waits` plus one hit per set reason flag.
    fn note_wait(&mut self, wait: WaitWake) {
        self.waits = self.waits.saturating_add(1);
        if wait.input {
            self.input = self.input.saturating_add(1);
        }
        if wait.ack {
            self.ack = self.ack.saturating_add(1);
        }
        if wait.message {
            self.msg = self.msg.saturating_add(1);
        }
        if wait.timeout {
            self.timeout = self.timeout.saturating_add(1);
        }
        if wait.failed {
            self.failed = self.failed.saturating_add(1);
        }
    }

    /// One ack-only early return (a subset of `waits`, never a full turn).
    fn note_ack_only(&mut self) {
        self.ack_only = self.ack_only.saturating_add(1);
    }
}

/// Message-only wait for the focus-settle and proof paths: the same pump as
/// [`pump_wait_with_intent`] with no intent or ack wake, so those paths never
/// consume or spin on the owner wakes. The recursive focus-settle pump
/// deliberately excludes the ack wake: ack accounting runs on the outer
/// loop, never inside nested settlement. These nested waits never touch the
/// outer `ow_*` wait counters below: only the product outer wait returns
/// count, so the trace summary distinguishes outer returns from
/// focus/proof waits by construction.
fn pump_wait(timeout_ms: u32) {
    pump_wait_with_intent(timeout_ms, None, None);
}

#[derive(Debug, Clone)]
struct ObservedWindow {
    hwnd: u64,
    token: String,
    /// Native outer rectangle from the same `GetWindowRect` read the frame
    /// insets were measured against: one coherent observe pair, never a
    /// second torn read.
    outer: Rect,
    visible: Rect,
    insets: FrameInsets,
    identity: ObservedTarget,
    facts: WindowFacts,
}

fn class_of(hwnd: HWND) -> String {
    let mut buf = [0u16; 256];
    let n = unsafe { GetClassNameW(hwnd, buf.as_mut_ptr(), buf.len() as i32) };
    if n <= 0 {
        return String::new();
    }
    String::from_utf16_lossy(&buf[..n as usize])
}

fn window_identity(hwnd: HWND, hwnd_u64: u64, me: &ProcessIdentity) -> Option<ObservedTarget> {
    let mut pid: u32 = 0;
    unsafe {
        GetWindowThreadProcessId(hwnd, &mut pid);
    }
    // The owner never tiles its own process. Its separate-process Settings
    // UI (same executable, settings class) is excluded at the dialog gate
    // below, not here.
    if pid == 0 || pid == me.pid {
        return None;
    }
    let held = HeldProcess::open(pid).ok()?;
    let ident = held.identity().ok()?;
    if ident.pid != pid {
        return None;
    }
    if ident.user_sid != me.user_sid || ident.session_id != me.session_id {
        return None;
    }
    let rid = held.integrity().ok()?;
    if !is_medium_rid(rid) {
        return None;
    }
    Some(ObservedTarget {
        hwnd: hwnd_u64,
        pid,
        process_creation: ident.process_creation,
        exe_path: ident.exe_path,
        user_sid: ident.user_sid,
        session_id: ident.session_id,
        tag: owned_tag(hwnd),
    })
}

/// Fresh foreground lifetime for renderer-posted frames: pid/creation plus
/// the visible-membership tag, or `None` when the foreground is missing,
/// ours, or unreadable. The renderer refuses narrowly on `None` per the
/// binding contract (no unprovable stale show); readable unchanged
/// foregrounds keep ordinary unfocused-hold behavior. The target/mover
/// fence still applies independently, and the owner re-fences on its next
/// refresh.
fn foreground_lifetime(me: &ProcessIdentity) -> Option<WindowLifetime> {
    let foreground = unsafe { GetForegroundWindow() } as usize as u64;
    if foreground == 0 {
        return None;
    }
    let identity = window_identity(foreground as isize as HWND, foreground, me)?;
    Some(WindowLifetime {
        pid: identity.pid,
        creation: identity.process_creation,
        member_tag: crate::product_hide::sys::read_member_tag(foreground),
    })
}

/// Owned-helper lifetime tag (`OmniTilerLifetime` property). Empty when
/// absent: generic windows never carry it, so proof allowlists requiring a
/// nonempty tag reject them before any write.
fn owned_tag(hwnd: HWND) -> String {
    use windows_sys::Win32::UI::WindowsAndMessaging::GetPropW;
    let name: Vec<u16> = crate::test_window::TEST_WINDOW_PROP
        .encode_utf16()
        .chain([0])
        .collect();
    let v = unsafe { GetPropW(hwnd, name.as_ptr()) };
    if v.is_null() {
        return String::new();
    }
    let token = v as usize as u64;
    if token == 0 {
        return String::new();
    }
    format!("{token:016x}")
}

/// Proof-only owned-helper verification: sibling executable, owned class,
/// lifetime tag, full process identity, and medium integrity via
/// [`crate::test_window::sys::query_owned`]. Generic windows (including
/// otherwise eligible ordinary apps) fail here even when their rectangles
/// look tileable.
fn verify_proof_owned(
    hwnd_u64: u64,
    expected: &AllowEntry,
    me: &ProcessIdentity,
) -> std::result::Result<(), &'static str> {
    let helper_exe =
        crate::test_window::sys::sibling_helper_exe().map_err(|_| "identity-changed")?;
    let snap =
        crate::test_window::sys::query_owned(hwnd_u64, &helper_exe, &me.user_sid, me.session_id)
            .map_err(|_| "identity-changed")?;
    if snap.tag != expected.tag || snap.tag.is_empty() {
        return Err("identity-changed");
    }
    if snap.process.pid != expected.pid
        || snap.process.process_creation != expected.process_creation
        || snap.process.user_sid != expected.user_sid
        || snap.process.session_id != expected.session_id
    {
        return Err("identity-changed");
    }
    if !crate::lifecycle::exe_paths_equal(&snap.process.exe_path, &expected.exe_path) {
        return Err("identity-changed");
    }
    Ok(())
}

/// Identity plus distinct window state known after identity resolution but
/// before any frame query: the stable token and the full frozen-matchable
/// identity survive even when DWM has no frame to read.
#[derive(Debug, Clone)]
pub struct KnownIdentity {
    pub identity: ObservedTarget,
    pub token: String,
}

/// Failure modes of [`observe_window`]. Identity and state stay available
/// independently of geometry: a minimized (or otherwise frameless) window
/// reports its known identity with an accurate reason instead of masquerading
/// as a changed identity, and its token stays stable across ticks.
#[derive(Debug, Clone)]
pub enum ObserveFailure {
    /// Identity never resolved (invisible, vanished, foreign session/SID,
    /// elevated, or unreadable owner): a true unknown, counted in aggregate.
    Unknown,
    /// Identity resolved: retain it, keep its token stable, and skip geometry
    /// with this reason. Boxed: the identity is large and only travels the
    /// cold failure path. `Minimized` is decided from window state before any
    /// frame query; `Unreadable` means the frames failed after identity.
    Known(Box<KnownIdentity>, SkipReason),
}

/// Observe one window fully: identity/state first, geometry second. `IsIconic`
/// is read before any frame query because iconic windows have no DWM frame;
/// a minimized window returns its known identity with `Minimized` rather than
/// an identity error. DWM cloak-query failure fails closed as `Unreadable`,
/// never as eligible. Fullscreen uses whole `rcMonitor` bounds via the
/// portable predicate: captionless covering any monitor's full rect, never
/// dimensions alone.
fn observe_window(
    hwnd: HWND,
    me: &ProcessIdentity,
    fulls: &[Rect],
    tokens: &mut TokenMap,
) -> std::result::Result<ObservedWindow, ObserveFailure> {
    use ObserveFailure::{Known, Unknown};
    if unsafe { IsWindowVisible(hwnd) } == 0 {
        return Err(Unknown);
    }
    let hwnd_u64 = hwnd as usize as u64;
    let identity = window_identity(hwnd, hwnd_u64, me).ok_or(Unknown)?;
    let token = tokens.token_for(hwnd_u64, &identity.process_creation);
    // Token clones below are per-failure (cold paths); the final use moves.
    let known = |reason| {
        Known(
            Box::new(KnownIdentity {
                identity: identity.clone(),
                token: token.clone(),
            }),
            reason,
        )
    };
    // Window state before frames: an iconic window has no composited frame,
    // so its DWM queries would fail spuriously below.
    if unsafe { IsIconic(hwnd) } != 0 {
        return Err(known(SkipReason::Minimized));
    }
    let mut outer_raw: RECT = unsafe { std::mem::zeroed() };
    if unsafe { GetWindowRect(hwnd, &mut outer_raw) } == 0 {
        return Err(known(SkipReason::Unreadable));
    }
    let outer = rect_from_win(outer_raw).ok_or_else(|| known(SkipReason::Unreadable))?;
    let mut visible_raw: RECT = unsafe { std::mem::zeroed() };
    let visible = if unsafe {
        DwmGetWindowAttribute(
            hwnd,
            DWMWA_EXTENDED_FRAME_BOUNDS,
            (&mut visible_raw as *mut RECT).cast(),
            std::mem::size_of::<RECT>() as u32,
        )
    } == 0
    {
        rect_from_win(visible_raw).ok_or_else(|| known(SkipReason::Unreadable))?
    } else {
        return Err(known(SkipReason::Unreadable));
    };
    if !tiler_core::bounds::valid_carried_rect(visible.x, visible.y, visible.w, visible.h) {
        return Err(known(SkipReason::Unreadable));
    }
    let mut cloaked: i32 = 0;
    if unsafe {
        DwmGetWindowAttribute(
            hwnd,
            DWMWA_CLOAKED,
            (&mut cloaked as *mut i32).cast(),
            std::mem::size_of::<i32>() as u32,
        )
    } != 0
    {
        return Err(known(SkipReason::Unreadable));
    }
    let style = unsafe { GetWindowLongW(hwnd, GWL_STYLE) } as u32;
    let exstyle = unsafe { GetWindowLongW(hwnd, GWL_EXSTYLE) } as u32;
    let owned = !unsafe { GetWindow(hwnd, GW_OWNER) }.is_null();
    let class = class_of(hwnd);
    let captionless = style & WS_CAPTION == 0;
    let facts = WindowFacts {
        visible: true,
        minimized: unsafe { IsIconic(hwnd) } != 0,
        maximized: unsafe { IsZoomed(hwnd) } != 0,
        cloaked: cloaked != 0,
        elevated: false,
        shell: is_shell_class(&class),
        tool_window: exstyle & WS_EX_TOOLWINDOW != 0,
        owned,
        captionless_fullscreen: is_borderless_fullscreen(captionless, visible, fulls),
        no_activate: exstyle & WS_EX_NOACTIVATE != 0,
        dialog: (!owned && class == DIALOG_CLASS)
            || crate::tiling::is_own_settings_window(&class, &identity.exe_path, &me.exe_path),
    };
    Ok(ObservedWindow {
        hwnd: hwnd_u64,
        token,
        outer,
        visible,
        insets: FrameInsets::measure(outer, visible),
        identity,
        facts,
    })
}

/// Slow or hung managed windows supply unknown instead of blocking the loop.
const MIN_HINT_TIMEOUT_MS: u32 = 10;

/// Share a deadline across domains, reserving most of the poll interval for
/// other work. Native identity/frame calls and scheduling are not hard realtime.
const MIN_HINT_OP_BUDGET_MS: u64 = (TICK_POLL_MS * 2 / 5) as u64;

/// `SendMessageTimeoutW` timeout failure code: distinguishes a hung-window
/// abort from any other setter failure.
const ERROR_TIMEOUT: u32 = 1460;

/// One minimum-hint query outcome for bounded summaries. `Hint` carries a
/// usable hint; every other variant maps to unknown (no hint).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HintOutcome {
    Hint,
    Timeout,
    Failed,
    Invalid,
    Budget,
}

impl HintOutcome {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Hint => "hint",
            Self::Timeout => "timeout",
            Self::Failed => "failed",
            Self::Invalid => "invalid",
            Self::Budget => "budget",
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct HintStats {
    queried: usize,
    with_hint: usize,
    timeout: usize,
    failed: usize,
    invalid: usize,
    budget_skipped: usize,
}

impl HintStats {
    fn note(&mut self, outcome: HintOutcome) {
        match outcome {
            HintOutcome::Hint => {
                self.queried += 1;
                self.with_hint += 1;
            }
            HintOutcome::Timeout => {
                self.queried += 1;
                self.timeout += 1;
            }
            HintOutcome::Failed => {
                self.queried += 1;
                self.failed += 1;
            }
            HintOutcome::Invalid => {
                self.queried += 1;
                self.invalid += 1;
            }
            HintOutcome::Budget => {
                self.budget_skipped += 1;
            }
        }
    }
}

/// Fresh query deadline shared by all domains in this operation.
struct HintCx {
    deadline: Instant,
}

impl HintCx {
    fn new() -> Self {
        Self {
            deadline: Instant::now() + Duration::from_millis(MIN_HINT_OP_BUDGET_MS),
        }
    }

    fn over_budget(&self) -> bool {
        Instant::now() >= self.deadline
    }

    fn timeout_ms(&self) -> u32 {
        self.deadline
            .saturating_duration_since(Instant::now())
            .as_millis()
            .min(u128::from(MIN_HINT_TIMEOUT_MS)) as u32
    }
}

// Test-only controlled fresh-hint results, keyed by HWND (see
// `inject_test_hints`): unit tests inject already-converted production
// hints here so assembly exercises the real query call sites without native
// windows; ordinary tests leave the map empty and keep the fail-closed
// native behavior. Compiled out of non-test builds: no production path can
// observe it.
#[cfg(test)]
thread_local! {
    static INJECTED_HINTS: std::cell::RefCell<std::collections::HashMap<u64, WindowSizeHints>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

/// Inject one controlled fresh-hint result for `hwnd` (test-only). Overwrites
/// any previous injection for the same window; [`clear_test_hints`] resets
/// all of them. Tests must use distinct fake HWNDs per member and clear
/// before arranging.
#[cfg(test)]
fn inject_test_hints(hwnd: u64, hints: WindowSizeHints) {
    INJECTED_HINTS.with(|map| {
        map.borrow_mut().insert(hwnd, hints);
    });
}

/// Drop every injected fresh-hint result (test-only).
#[cfg(test)]
fn clear_test_hints() {
    INJECTED_HINTS.with(|map| {
        map.borrow_mut().clear();
    });
}

/// Controlled fresh-hint result for `hwnd`, if injected (test-only). The
/// outcome mirrors the conversion rule: non-empty hints read `Hint`,
/// empty hints read `Invalid`.
#[cfg(test)]
fn test_hint_for(hwnd: u64) -> Option<(WindowSizeHints, HintOutcome)> {
    INJECTED_HINTS
        .with(|map| map.borrow().get(&hwnd).copied())
        .map(|hints| {
            let outcome = if hints.is_empty() {
                HintOutcome::Invalid
            } else {
                HintOutcome::Hint
            };
            (hints, outcome)
        })
}

// Pending-drop owner-integration seams (test-only, offline, native-free).
// Each injector is `None` in ordinary tests (fail-closed native behavior);
// pending fixtures set them to script deterministic owner reads/effects
// without creating windows, hooks, or mutating the desktop. All use safe
// `std` only, mirroring the existing `INJECTED_HINTS` pattern.
#[cfg(test)]
thread_local! {
    #[allow(clippy::type_complexity)]
    static INJECTED_OBSERVE: std::cell::RefCell<
        Option<(Vec<ObservedWindow>, Vec<RetainedRow>, bool)>,
    > = const { std::cell::RefCell::new(None) };
    #[allow(clippy::missing_const_for_thread_local)]
    static INJECTED_TAGS: std::cell::RefCell<std::collections::HashMap<u64, Option<String>>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
    static INJECTED_TAGS_ACTIVE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static INJECTED_SUSPEND: std::cell::Cell<Option<bool>> = const { std::cell::Cell::new(None) };
    static INJECTED_ELEVATED: std::cell::Cell<Option<bool>> = const { std::cell::Cell::new(None) };
    static INJECTED_FOCUS: std::cell::RefCell<Option<&'static str>> =
        const { std::cell::RefCell::new(None) };
    static INJECTED_STOP: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static PENDING_COUNTERS: std::cell::RefCell<PendingCounters> =
        const { std::cell::RefCell::new(PendingCounters::new()) };
    /// Scripted geometry-apply verdicts for cross-operation tails (one
    /// `(readback_ok, mismatched)` per stubbed apply, consumed in order):
    /// the stubbed apply returns the next scripted verdict instead of
    /// success so full-path refusal tests can inject failed readback/writes
    /// without native effects. Empty keeps the success stub. A single
    /// entry fails only the next apply; two entries script the
    /// destination-then-source applies of the empty flow independently.
    static INJECTED_APPLY: std::cell::RefCell<std::collections::VecDeque<(bool, usize)>> =
        const { std::cell::RefCell::new(std::collections::VecDeque::new()) };
    /// Recorded writable-token sets, one per stubbed geometry apply, in
    /// call order: lets full-path fixtures assert exactly which tokens a
    /// transfer scoped for writes (mover excluded, occupants present)
    /// without native effects. Recorded only while the injected observation
    /// fixture is active; cleared by [`clear_pending_seams`].
    static APPLY_WRITABLES: std::cell::RefCell<Vec<std::collections::BTreeSet<String>>> =
        const { std::cell::RefCell::new(Vec::new()) };
    /// Scripted live overlay reads `(maximized, fullscreen)` for output-send
    /// tails (one entry per `live_overlay_flags` call, consumed in order):
    /// lets full-path fixtures script a stable overlay snapshot through the
    /// dispatch gate plus both fence reads, or drift between the pre-write
    /// and post-write reads, without native windows. Empty keeps the
    /// production read (fail-closed on foreign HWNDs).
    static INJECTED_OVERLAY: std::cell::RefCell<std::collections::VecDeque<(bool, Option<bool>)>> =
        const { std::cell::RefCell::new(std::collections::VecDeque::new()) };
    /// Iconic HWNDs for the injected observation fixture: production
    /// `EnumWindows` yields iconic windows and `observe` resolves them to
    /// known-minimized (omitted rows, stable tokens). The injected
    /// `observe` path therefore joins these HWNDs into the inventory and
    /// marks matching member keys omitted, mirroring the real arm without
    /// native queries. Unknown HWNDs are ignored (no membership).
    static INJECTED_ICONIC: std::cell::RefCell<std::collections::HashSet<u64>> =
        std::cell::RefCell::new(std::collections::HashSet::new());
    static INJECTED_ICONIC_ACTIVE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    /// Enumerated-but-unresolved HWNDs for the injected observation
    /// fixture: production windows whose identity or frames fail stay in
    /// the raw inventory (`Unknown`) without tokens or rows. The injected
    /// path joins them into the inventory only, so cleanup never mistakes
    /// them for closes and assembly defers instead of fabricating rows.
    static INJECTED_UNREADABLE: std::cell::RefCell<std::collections::HashSet<u64>> =
        std::cell::RefCell::new(std::collections::HashSet::new());
    /// Scripted hidden-claim recovery verdicts per HWND: `Ok` snapshots
    /// flow through the real audit classification (process/nonce compared
    /// against the stored claim); `Err` strings use the production
    /// vocabulary (`absent:*` / `refuse: sid/session mismatch` retire,
    /// anything else retains). Unscripted HWNDs while active retain as
    /// `uncertain` without a native call.
    static INJECTED_RECOVERY: std::cell::RefCell<
        std::collections::HashMap<
            u64,
            std::result::Result<crate::product_hide::sys::ProductSnapshot, String>,
        >,
    > = std::cell::RefCell::new(std::collections::HashMap::new());
    static INJECTED_RECOVERY_ACTIVE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    /// Fresh native arrival readback per HWND (test-only): the post-setter
    /// physical frame distinctly from the pre-move `stable` cache. Visible
    /// members (tiled plain, float, overlay) stage their post-move visible
    /// (DWM extended-frame) rect here, never the outer `GetWindowRect`;
    /// concealed members (minimized/hidden) stage their post-move
    /// `WINDOWPLACEMENT` normal rect in screen coordinates here (the
    /// production readback converts workspace to screen before proving).
    /// Unscripted HWNDs read as `None` (arrival unverified, never the stale
    /// cache, never translation math). Cleared by [`clear_pending_seams`].
    static INJECTED_ARRIVAL: std::cell::RefCell<std::collections::HashMap<u64, Rect>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
    static INJECTED_ARRIVAL_PLACEMENT: std::cell::RefCell<std::collections::HashMap<u64, Rect>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
    /// Live `WINDOWPLACEMENT` normal rect plus workspace-coordinate basis per
    /// HWND (test-only): the pre-setter restore frame for the maximized
    /// overlay remap and the placement-screen conversion. The rect rides the
    /// raw `rcNormalPosition` basis (workspace for non-tool top-level,
    /// screen for tool windows); the flag records which. Unscripted HWNDs
    /// read as `None` (fail-closed, never a retained fallback).
    static INJECTED_PLACEMENT_NORMALS: std::cell::RefCell<
        std::collections::HashMap<u64, (Rect, bool)>,
    > = std::cell::RefCell::new(std::collections::HashMap::new());
    static INJECTED_FLOAT_MOVES: std::cell::RefCell<Vec<(u64, Rect)>> =
        const { std::cell::RefCell::new(Vec::new()) };
    static INJECTED_FLOAT_MOVE_OK: std::cell::Cell<bool> = const { std::cell::Cell::new(true) };
    /// Recorded ALL-member native output transfers `(hwnd, moved rect, kind)`
    /// in call order (test-only): the exact production helper boundary
    /// arguments for every float/overlay/minimized/hidden remap. `kind` is
    /// `float`, `overlay`, `minimized` or `hidden`. Recorded by the real
    /// helpers (test arm) so regressions prove which members attempted a
    /// native move, not just the tiled apply. Cleared by
    /// [`clear_pending_seams`].
    static INJECTED_NATIVE_TRANSFERS: std::cell::RefCell<Vec<(u64, Rect, &'static str)>> =
        const { std::cell::RefCell::new(Vec::new()) };
    /// Setter verdict for overlay/minimized/hidden placement and overlay
    /// moves (test-only): `false` simulates a refused native setter without
    /// touching native state. Float moves keep their own
    /// `INJECTED_FLOAT_MOVE_OK` cell; this cell gates the other kinds.
    static INJECTED_NATIVE_MOVE_OK: std::cell::Cell<bool> = const { std::cell::Cell::new(true) };
}

